(function() {
  'use strict';

  const AeroTheme = {
    // 默认配置
    defaultConfig: {
      glassOpacity: 0.7,
      blurAmount: 20,
      reflectionIntensity: 0.3,
      animationSpeed: 'normal',
      colorScheme: 'blue',
      enableTrueTransparency: true,
      backgroundTransparency: 0.2,
      enableMouseTracking: true,
      autoEnhanceElements: true
    },

    config: null,

    colorSchemes: {
      blue: {
        base: { r: 173, g: 216, b: 230 },
        primary: 'rgba(173, 216, 230, 0.7)',
        secondary: 'rgba(135, 206, 235, 0.7)',
        accent: 'rgba(100, 149, 237, 0.7)',
        background: 'rgba(240, 248, 255, 0.85)'
      },
      green: {
        base: { r: 152, g: 251, b: 152 },
        primary: 'rgba(152, 251, 152, 0.7)',
        secondary: 'rgba(144, 238, 144, 0.7)',
        accent: 'rgba(60, 179, 113, 0.7)',
        background: 'rgba(240, 255, 240, 0.85)'
      },
      purple: {
        base: { r: 221, g: 160, b: 221 },
        primary: 'rgba(221, 160, 221, 0.7)',
        secondary: 'rgba(218, 112, 214, 0.7)',
        accent: 'rgba(147, 112, 219, 0.7)',
        background: 'rgba(248, 240, 255, 0.85)'
      },
      orange: {
        base: { r: 255, g: 218, b: 185 },
        primary: 'rgba(255, 218, 185, 0.7)',
        secondary: 'rgba(255, 160, 122, 0.7)',
        accent: 'rgba(255, 127, 80, 0.7)',
        background: 'rgba(255, 250, 240, 0.85)'
      }
    },

    observer: null,

    init() {
      console.log('Aero Glass 主题插件 v2.2 已加载');

      // 从数据库配置加载（通过$plugin全局变量）
      this.loadConfig();

      // 监听配置更新事件
      window.addEventListener('plugin-settings-updated', (e) => {
        if (e.detail.pluginId === 'aero-glass-theme-1733500000000abc') {
          console.log('收到配置更新:', e.detail.settings);
          this.config = { ...this.defaultConfig, ...e.detail.settings };
          this.applyTheme();

          // 重新初始化动态效果
          if (this.observer) {
            this.observer.disconnect();
            this.observer = null;
          }

          if (this.config.autoEnhanceElements) {
            this.addDynamicEffects();
          } else {
            this.removeEnhancements();
          }

          if (this.config.enableMouseTracking) {
            this.setupWindowEffects();
          }
        }
      });

      // 应用主题
      this.applyTheme();

      // 添加动态效果
      if (this.config.autoEnhanceElements) {
        this.addDynamicEffects();
      }

      // 添加窗口效果
      if (this.config.enableMouseTracking) {
        this.setupWindowEffects();
      }
    },

    // 加载配置（从数据库）
    loadConfig() {
      // 优先从全局$plugin对象获取数据库配置
      if (typeof $plugin !== 'undefined' && $plugin && $plugin.config) {
        this.config = { ...this.defaultConfig, ...$plugin.config };
        console.log('已从数据库加载配置:', this.config);
      } else {
        // 降级：从localStorage读取（兼容旧版本）
        const saved = localStorage.getItem('plugin-settings-aero-glass-theme-1733500000000abc');
        if (saved) {
          try {
            this.config = { ...this.defaultConfig, ...JSON.parse(saved) };
            console.log('已从localStorage加载配置:', this.config);
          } catch (e) {
            console.error('配置加载失败，使用默认配置:', e);
            this.config = { ...this.defaultConfig };
          }
        } else {
          this.config = { ...this.defaultConfig };
          console.log('使用默认配置');
        }
      }
    },

    // 应用主题
    applyTheme() {
      const scheme = this.colorSchemes[this.config.colorScheme];
      const root = document.documentElement;

      // 计算透明度相关的颜色
      const bgTransparency = this.config.enableTrueTransparency ? this.config.backgroundTransparency : 0;
      const base = scheme.base;

      // 动态计算带透明度的颜色
      const primaryColor = `rgba(${base.r}, ${base.g}, ${base.b}, ${Math.max(0.3, this.config.glassOpacity - bgTransparency)})`;
      const bgColor = `rgba(${base.r + 60}, ${base.g + 30}, ${base.b + 20}, ${Math.max(0.1, 0.85 - bgTransparency)})`;

      // 设置CSS变量
      root.style.setProperty('--aero-primary', primaryColor);
      root.style.setProperty('--aero-secondary', scheme.secondary);
      root.style.setProperty('--aero-accent', scheme.accent);
      root.style.setProperty('--aero-background', bgColor);
      root.style.setProperty('--aero-blur', `${this.config.blurAmount}px`);
      root.style.setProperty('--aero-opacity', this.config.glassOpacity);
      root.style.setProperty('--aero-reflection', this.config.reflectionIntensity);
      root.style.setProperty('--aero-bg-transparency', bgTransparency);

      // 设置动画速度
      const speed = this.config.animationSpeed === 'fast' ? '0.2s' : 
                    this.config.animationSpeed === 'slow' ? '0.6s' : '0.4s';
      root.style.setProperty('--aero-transition-speed', speed);

      // 添加/移除透明类
      if (this.config.enableTrueTransparency) {
        document.body.classList.add('aero-true-transparency');
      } else {
        document.body.classList.remove('aero-true-transparency');
      }

      // 添加主题类名
      document.body.classList.add('aero-theme-active');

      console.log(`Aero主题已应用: ${this.config.colorScheme}, 真实透明: ${this.config.enableTrueTransparency}, 透明度: ${bgTransparency}`);
    },

    // 添加动态效果
    addDynamicEffects() {
      // 停止旧的观察器
      if (this.observer) {
        this.observer.disconnect();
      }

      // 为所有卡片添加悬停效果
      this.observer = new MutationObserver(() => {
        this.enhanceElements();
      });

      this.observer.observe(document.body, {
        childList: true,
        subtree: true
      });

      this.enhanceElements();
    },

    // 增强元素效果
    enhanceElements() {
      if (!this.config.autoEnhanceElements) return;

      // 增强卡片
      const cards = document.querySelectorAll('.v-card:not(.aero-enhanced)');
      cards.forEach(card => {
        card.classList.add('aero-enhanced', 'aero-glass');
      });

      // 增强对话框
      const dialogs = document.querySelectorAll('.v-dialog .v-card:not(.aero-enhanced)');
      dialogs.forEach(dialog => {
        dialog.classList.add('aero-enhanced', 'aero-glass-dialog');
      });

      // 增强导航栏
      const navs = document.querySelectorAll('.v-navigation-drawer:not(.aero-enhanced)');
      navs.forEach(nav => {
        nav.classList.add('aero-enhanced', 'aero-glass-nav');
      });

      // 增强应用栏
      const appBars = document.querySelectorAll('.v-app-bar:not(.aero-enhanced)');
      appBars.forEach(bar => {
        bar.classList.add('aero-enhanced', 'aero-glass-bar');
      });
    },

    // 移除增强效果
    removeEnhancements() {
      const enhanced = document.querySelectorAll('.aero-enhanced');
      enhanced.forEach(el => {
        el.classList.remove('aero-enhanced', 'aero-glass', 'aero-glass-dialog', 'aero-glass-nav', 'aero-glass-bar');
      });
    },

    // 设置窗口效果
    setupWindowEffects() {
      if (!this.config.enableMouseTracking) return;

      // 创建光标跟随效果
      let mouseX = 0, mouseY = 0;

      document.addEventListener('mousemove', (e) => {
        mouseX = e.clientX;
        mouseY = e.clientY;

        // 更新光影位置
        const glassElements = document.querySelectorAll('.aero-glass');
        glassElements.forEach(el => {
          const rect = el.getBoundingClientRect();
          const centerX = rect.left + rect.width / 2;
          const centerY = rect.top + rect.height / 2;

          const deltaX = (mouseX - centerX) / rect.width;
          const deltaY = (mouseY - centerY) / rect.height;

          el.style.setProperty('--mouse-x', deltaX);
          el.style.setProperty('--mouse-y', deltaY);
        });
      });
    }
  };

  // 全局暴露
  window.aeroTheme = AeroTheme;

  // 初始化
  AeroTheme.init();
})();

