/* Aero Glass 主题样式 v2.2 - 支持真实透明效果 */

/* CSS变量定义 */
:root {
  --aero-primary: rgba(173, 216, 230, 0.7);
  --aero-secondary: rgba(135, 206, 235, 0.7);
  --aero-accent: rgba(100, 149, 237, 0.7);
  --aero-background: rgba(240, 248, 255, 0.85);
  --aero-blur: 20px;
  --aero-opacity: 0.7;
  --aero-reflection: 0.3;
  --aero-transition-speed: 0.4s;
  --aero-bg-transparency: 0;
  --mouse-x: 0;
  --mouse-y: 0;
}

/* 全局背景 - 默认半透明渐变 */
body.aero-theme-active {
  background: linear-gradient(135deg, 
    rgba(173, 216, 230, 0.3) 0%, 
    rgba(135, 206, 235, 0.2) 50%, 
    rgba(100, 149, 237, 0.3) 100%);
  background-attachment: fixed;
}

/* 真实透明模式 - 背景更透明 */
body.aero-theme-active.aero-true-transparency {
  background: linear-gradient(135deg, 
    rgba(173, 216, 230, calc(0.3 - var(--aero-bg-transparency))) 0%, 
    rgba(135, 206, 235, calc(0.2 - var(--aero-bg-transparency))) 50%, 
    rgba(100, 149, 237, calc(0.3 - var(--aero-bg-transparency))) 100%);
  background-attachment: fixed;
}

/* 毛玻璃效果基类 */
.aero-glass {
  position: relative;
  background: var(--aero-background) !important;
  backdrop-filter: blur(var(--aero-blur)) saturate(180%);
  -webkit-backdrop-filter: blur(var(--aero-blur)) saturate(180%);
  border: 1px solid rgba(255, 255, 255, 0.3) !important;
  box-shadow: 
    0 8px 32px 0 rgba(31, 38, 135, 0.15),
    inset 0 1px 0 0 rgba(255, 255, 255, 0.5),
    inset 0 -1px 0 0 rgba(0, 0, 0, 0.1) !important;
  transition: all var(--aero-transition-speed) cubic-bezier(0.4, 0, 0.2, 1);
  overflow: hidden;
}

/* 真实透明模式下的玻璃效果 */
body.aero-true-transparency .aero-glass {
  background: var(--aero-background) !important;
  backdrop-filter: blur(var(--aero-blur)) saturate(200%);
  -webkit-backdrop-filter: blur(var(--aero-blur)) saturate(200%);
  border: 1px solid rgba(255, 255, 255, 0.4) !important;
  box-shadow: 
    0 8px 32px 0 rgba(31, 38, 135, 0.2),
    inset 0 1px 0 0 rgba(255, 255, 255, 0.6),
    inset 0 -1px 0 0 rgba(0, 0, 0, 0.15) !important;
}

/* 玻璃反光效果 */
.aero-glass::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, calc(var(--aero-reflection) * 0.6)) 0%,
    transparent 50%,
    rgba(0, 0, 0, calc(var(--aero-reflection) * 0.3)) 100%
  );
  pointer-events: none;
  opacity: 0.6;
  transition: opacity var(--aero-transition-speed);
}

/* 真实透明模式下的反光效果更明显 */
body.aero-true-transparency .aero-glass::before {
  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, calc(var(--aero-reflection) * 0.8)) 0%,
    transparent 45%,
    rgba(0, 0, 0, calc(var(--aero-reflection) * 0.4)) 100%
  );
  opacity: 0.7;
}

/* 光标响应效果 */
.aero-glass::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: radial-gradient(
    circle at calc(50% + var(--mouse-x) * 100px) calc(50% + var(--mouse-y) * 100px),
    rgba(255, 255, 255, 0.15),
    transparent 60%
  );
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.3s;
}

.aero-glass:hover::after {
  opacity: 1;
}

/* 卡片悬停效果 */
.aero-glass:hover {
  transform: translateY(-4px) scale(1.02);
  box-shadow: 
    0 16px 48px 0 rgba(31, 38, 135, 0.25),
    inset 0 1px 0 0 rgba(255, 255, 255, 0.6),
    inset 0 -1px 0 0 rgba(0, 0, 0, 0.1) !important;
  border-color: rgba(255, 255, 255, 0.5) !important;
}

/* 对话框样式 */
.aero-glass-dialog {
  background: var(--aero-background) !important;
  backdrop-filter: blur(calc(var(--aero-blur) * 1.5)) saturate(200%);
  -webkit-backdrop-filter: blur(calc(var(--aero-blur) * 1.5)) saturate(200%);
  box-shadow: 
    0 20px 60px 0 rgba(31, 38, 135, 0.3),
    inset 0 2px 0 0 rgba(255, 255, 255, 0.6) !important;
}

/* 导航栏样式 */
.aero-glass-nav {
  background: var(--aero-primary) !important;
  backdrop-filter: blur(var(--aero-blur)) saturate(180%);
  -webkit-backdrop-filter: blur(var(--aero-blur)) saturate(180%);
  border-right: 1px solid rgba(255, 255, 255, 0.3) !important;
}

/* 应用栏样式 */
.aero-glass-bar {
  background: var(--aero-secondary) !important;
  backdrop-filter: blur(var(--aero-blur)) saturate(180%);
  -webkit-backdrop-filter: blur(var(--aero-blur)) saturate(180%);
  border-bottom: 1px solid rgba(255, 255, 255, 0.3) !important;
}

/* 真实透明模式下的导航栏和应用栏 */
body.aero-true-transparency .aero-glass-nav,
body.aero-true-transparency .aero-glass-bar {
  backdrop-filter: blur(calc(var(--aero-blur) * 1.2)) saturate(200%);
  -webkit-backdrop-filter: blur(calc(var(--aero-blur) * 1.2)) saturate(200%);
  border-color: rgba(255, 255, 255, 0.4) !important;
}

/* 响应式设计 */
@media (max-width: 768px) {
  .aero-glass {
    backdrop-filter: blur(calc(var(--aero-blur) * 0.8)) saturate(150%);
    -webkit-backdrop-filter: blur(calc(var(--aero-blur) * 0.8)) saturate(150%);
  }

  /* 移动端降低悬停效果 */
  .aero-glass:hover {
    transform: none;
  }
}

/* 暗色模式适配 */
@media (prefers-color-scheme: dark) {
  body.aero-theme-active {
    background: linear-gradient(135deg, 
      rgba(30, 30, 60, 0.9) 0%, 
      rgba(20, 20, 50, 0.9) 50%, 
      rgba(10, 10, 40, 0.9) 100%);
  }

  body.aero-theme-active.aero-true-transparency {
    background: linear-gradient(135deg, 
      rgba(30, 30, 60, calc(0.7 - var(--aero-bg-transparency))) 0%, 
      rgba(20, 20, 50, calc(0.6 - var(--aero-bg-transparency))) 50%, 
      rgba(10, 10, 40, calc(0.7 - var(--aero-bg-transparency))) 100%);
  }

  .aero-glass {
    background: rgba(40, 40, 80, 0.7) !important;
    border-color: rgba(255, 255, 255, 0.15) !important;
  }

  body.aero-true-transparency .aero-glass {
    background: rgba(40, 40, 80, calc(0.5 - var(--aero-bg-transparency) * 0.5)) !important;
    border-color: rgba(255, 255, 255, 0.25) !important;
  }
}

/* 辅助功能 */
@media (prefers-reduced-motion: reduce) {
  .aero-glass,
  .aero-glass::before,
  .aero-glass::after {
    transition: none !important;
    animation: none !important;
  }
}

/* 高对比度模式 */
@media (prefers-contrast: high) {
  .aero-glass {
    border-width: 2px !important;
    border-color: rgba(0, 0, 0, 0.5) !important;
  }
}
